#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>

#define MAX_CMD_LEN 64
#define LISTEN_PORT 8443

typedef struct {
    char command[MAX_CMD_LEN];
    char args[MAX_CMD_LEN];
    int privilege_level;
} cli_request_t;

// Parse incoming CLI command from network socket
int parse_cli_command(const char *input, cli_request_t *req) {
    memset(req, 0, sizeof(cli_request_t));

    // Extract command name - vulnerable: no bounds check on input length
    char *space = strchr(input, ' ');
    if (space) {
        size_t cmd_len = space - input;
        // BUG: cmd_len can exceed MAX_CMD_LEN, causing stack buffer overflow
        memcpy(req->command, input, cmd_len);
        req->command[cmd_len] = '\0';

        // Copy arguments - also vulnerable to overflow
        strcpy(req->args, space + 1);
    } else {
        // No arguments - still no length check
        strcpy(req->command, input);
    }

    return 0;
}

int execute_command(cli_request_t *req) {
    if (strcmp(req->command, "status") == 0) {
        return system("systemctl status myservice");
    } else if (strcmp(req->command, "restart") == 0) {
        if (req->privilege_level >= 2) {
            return system("systemctl restart myservice");
        }
        return -1;
    } else if (strcmp(req->command, "config") == 0) {
        char path[128];
        // Secondary vuln: format string is safe but path traversal possible
        snprintf(path, sizeof(path), "/etc/myservice/%s.conf", req->args);
        return system(path);
    }
    return -1;
}

int main(int argc, char *argv[]) {
    int server_fd, client_fd;
    struct sockaddr_in addr;
    char buffer[1024];

    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = INADDR_ANY;
    addr.sin_port = htons(LISTEN_PORT);

    bind(server_fd, (struct sockaddr*)&addr, sizeof(addr));
    listen(server_fd, 5);

    printf("CLI service listening on port %d\n", LISTEN_PORT);

    while (1) {
        client_fd = accept(server_fd, NULL, NULL);
        if (client_fd < 0) continue;

        ssize_t n = read(client_fd, buffer, sizeof(buffer) - 1);
        if (n > 0) {
            buffer[n] = '\0';
            // Strip newline
            char *nl = strchr(buffer, '\n');
            if (nl) *nl = '\0';

            cli_request_t req;
            parse_cli_command(buffer, &req);

            int result = execute_command(&req);

            char response[256];
            snprintf(response, sizeof(response), "Result: %d\n", result);
            write(client_fd, response, strlen(response));
        }
        close(client_fd);
    }

    return 0;
}
